using ManpowerManagement.Data;using ManpowerManagement.Models;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;
namespace ManpowerManagement.Pages.Tickets;
public class ManageModel(AppDbContext db):PageModel{public List<ResignationTicket> Tickets{get;set;}=[];public async Task OnGetAsync()=>Tickets=await db.ResignationTickets.Include(x=>x.Employee).Include(x=>x.Workshop).Where(x=>x.Status==TicketStatus.Submitted).OrderBy(x=>x.SubmittedAtUtc).ToListAsync();public async Task<IActionResult> OnPostAsync(int id,string decision,DateOnly effectiveDate){var t=await db.ResignationTickets.Include(x=>x.Employee).SingleOrDefaultAsync(x=>x.Id==id);if(t==null)return NotFound();t.DecisionBy=User.Identity?.Name;t.Status=decision=="approve"?TicketStatus.Approved:TicketStatus.Rejected;if(t.Status==TicketStatus.Approved&&t.Employee!=null){t.EffectiveResignedDate=effectiveDate;t.Employee.ResignedDate=effectiveDate;if(effectiveDate<DateOnly.FromDateTime(DateTime.Today))t.Employee.EmploymentState=EmploymentState.Resigned;}db.AuditLogs.Add(new AuditLog{EntityName="ResignationTicket",EntityKey=id.ToString(),Action=t.Status.ToString(),Actor=t.DecisionBy??"Approver"});await db.SaveChangesAsync();return RedirectToPage();}}
